VALUES ('kepserver-device', 'KEPServer导入设备', '由洗煤厂设备新.csv自动导入的现场设备', 1, 100, 'ENABLED')
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, level = EXCLUDED.level, sort = EXCLUDED.sort, status = EXCLUDED.status;

ON CONFLICT (device_id) DO UPDATE SET name = EXCLUDED.name, status = EXCLUDED.status, description = EXCLUDED.description;

ON CONFLICT (tag_code) DO UPDATE SET tag_name = EXCLUDED.tag_name, source_type = EXCLUDED.source_type, source_path = EXCLUDED.source_path, device_code = EXCLUDED.device_code, device_name = EXCLUDED.device_name, area_code = EXCLUDED.area_code, data_type = EXCLUDED.data_type, unit = EXCLUDED.unit, scan_rate = EXCLUDED.scan_rate, quality_rule = EXCLUDED.quality_rule, enabled = EXCLUDED.enabled, remark = EXCLUDED.remark, updated_at = NOW();

ON CONFLICT (mapping_id) DO UPDATE SET tag_code = EXCLUDED.tag_code, business_code = EXCLUDED.business_code, business_name = EXCLUDED.business_name, source_path = EXCLUDED.source_path, transform_rule = EXCLUDED.transform_rule, enabled = EXCLUDED.enabled, remark = EXCLUDED.remark, updated_at = NOW();

